import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class TestHarness {
  static final String[] FIELDS = {"size", "dogs", "minutes", "hour"};
  static final Object[][] VALUES = {{'M', 2, 75, 19}, {'S', 1, 45, 6}, {'L', 3, 60, 22}, {'M', 1, 60, 7}, {'X', 2, 50, 21}, {'S', 2, 120, 0}, {'L', 2, 90, 12}};
  static final String[] EXPECTED = {"RG9nczogMiB4IE0sIDEgaCAxNSBtaW4KRGlzY291bnQ6IDEwJQpUb3RhbDogOTAwIHJ1Ygo=", "RG9nczogMSB4IFMsIDAgaCA0NSBtaW4KRGlzY291bnQ6IG5vbmUKVG90YWw6IDMyNSBydWIK", "RG9nczogMyB4IEwsIDEgaCAwIG1pbgpEaXNjb3VudDogMTAlClRvdGFsOiAxNDUwIHJ1Ygo=", "RG9nczogMSB4IE0sIDEgaCAwIG1pbgpEaXNjb3VudDogbm9uZQpUb3RhbDogNDAwIHJ1Ygo=", "RG9nczogMiB4IFgsIDAgaCA1MCBtaW4KRGlzY291bnQ6IG5vbmUKVG90YWw6IDgzMyBydWIK", "RG9nczogMiB4IFMsIDIgaCAwIG1pbgpEaXNjb3VudDogMTAlClRvdGFsOiAxMTgwIHJ1Ygo=", "RG9nczogMiB4IEwsIDEgaCAzMCBtaW4KRGlzY291bnQ6IDEwJQpUb3RhbDogMTM1MCBydWIK"};

  static String dec(String b) { return new String(Base64.getDecoder().decode(b), StandardCharsets.UTF_8); }
  static String show(String s) { String t = s.replace("\n", "\u21b5"); return t.length() > 200 ? t.substring(0, 200) + "\u2026" : t; }
  static void need(boolean ok, String message) { if (!ok) throw new AssertionError(message); }
  static Class<?> cls(String name) { try { return Class.forName(name, false, Solution.class.getClassLoader()); } catch (ClassNotFoundException e) { return null; } }
  static void setStatic(String cls, String field, Object value) throws Exception {
    Class<?> c = cls(cls); if (c == null) return;
    try { Field f = c.getDeclaredField(field); f.setAccessible(true); if (Modifier.isStatic(f.getModifiers()) && !Modifier.isFinal(f.getModifiers())) f.set(null, value); } catch (NoSuchFieldException ignored) { }
  }
  static void reset() throws Exception {
  }
  static void checks() throws Exception {
    boolean usesSwitch = true;
    try (InputStream in = Solution.class.getResourceAsStream("Solution.class")) {
        if (in != null) {
            DataInputStream d = new DataInputStream(new ByteArrayInputStream(in.readAllBytes()));
            d.skipBytes(8);
            int poolSize = d.readUnsignedShort();
            String[] utf = new String[poolSize];
            for (int i = 1; i < poolSize; i++) {
                int tag = d.readUnsignedByte();
                if (tag == 1) utf[i] = d.readUTF();
                else if (tag == 5 || tag == 6) { d.skipBytes(8); i++; }
                else if (tag == 7 || tag == 8 || tag == 16 || tag == 19 || tag == 20) d.skipBytes(2);
                else if (tag == 15) d.skipBytes(3);
                else d.skipBytes(4);
            }
            d.skipBytes(6);
            d.skipBytes(2 * d.readUnsignedShort());
            usesSwitch = false;
            for (int part = 0; part < 2; part++) {
                int members = d.readUnsignedShort();
                for (int m = 0; m < members; m++) {
                    d.skipBytes(6);
                    int attributes = d.readUnsignedShort();
                    for (int k = 0; k < attributes; k++) {
                        String name = utf[d.readUnsignedShort()];
                        byte[] a = new byte[d.readInt()];
                        d.readFully(a);
                        if (part == 0 || !"Code".equals(name)) continue;
                        int end = 8 + (((a[4] & 255) << 24) | ((a[5] & 255) << 16) | ((a[6] & 255) << 8) | (a[7] & 255));
                        for (int pc = 8; pc < end && !usesSwitch; ) {
                            int op = a[pc] & 255;
                            if (op == 0xaa || op == 0xab) usesSwitch = true;
                            else if (op == 0xc4) pc += (a[pc + 1] & 255) == 0x84 ? 6 : 4;
                            else if (op == 0x10 || op == 0x12 || (op >= 0x15 && op <= 0x19) || (op >= 0x36 && op <= 0x3a) || op == 0xa9 || op == 0xbc) pc += 2;
                            else if (op == 0x11 || op == 0x13 || op == 0x14 || op == 0x84 || (op >= 0x99 && op <= 0xa8) || (op >= 0xb2 && op <= 0xb8) || op == 0xbb || op == 0xbd || op == 0xc0 || op == 0xc1 || op == 0xc6 || op == 0xc7) pc += 3;
                            else if (op == 0xc5) pc += 4;
                            else if (op == 0xb9 || op == 0xba || op == 0xc8 || op == 0xc9) pc += 5;
                            else pc += 1;
                        }
                    }
                }
            }
        }
    } catch (Exception e) {
        usesSwitch = true;
    }
    need(usesSwitch, "Используй оператор switch по полю size: выбор одного варианта из многих по значению так читается проще, чем цепочка if");
  }

  static String run(int i) throws Throwable {
    for (int k = 0; k < FIELDS.length; k++) {
      Field f;
      try { f = Solution.class.getDeclaredField(FIELDS[k]); }
      catch (NoSuchFieldException e) { throw new AssertionError("Не удаляй и не переименовывай поле " + FIELDS[k] + " из заготовки: при проверке в него подставляются другие значения"); }
      if (!Modifier.isStatic(f.getModifiers()) || Modifier.isFinal(f.getModifiers())) throw new AssertionError("Поле " + FIELDS[k] + " должно остаться static и без final, как в заготовке");
      f.setAccessible(true); f.set(null, VALUES[i][k]);
    }
    reset();
    PrintStream out = System.out; ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    System.setOut(new PrintStream(buffer, true, "UTF-8"));
    try { Solution.main(new String[0]); } finally { System.setOut(out); }
    return buffer.toString("UTF-8");
  }

  public static void main(String[] args) throws Throwable {
    checks();
    String actual = run(0), expected = dec(EXPECTED[0]);
    if (!actual.equals(expected)) throw new AssertionError("Вывод не совпадает с примером: ожидалось «" + show(expected) + "», получилось «" + show(actual) + "»");
    int total = VALUES.length - 1;
    for (int i = 1; i < VALUES.length; i++) {
      String other;
      try { other = run(i); }
      catch (AssertionError e) { throw e; }
      catch (Throwable e) { Throwable cause = e instanceof InvocationTargetException && e.getCause() != null ? e.getCause() : e; throw new AssertionError("Проверка " + i + " из " + total + ": с другими значениями полей программа завершилась с ошибкой " + cause.getClass().getSimpleName()); }
      if (!other.equals(dec(EXPECTED[i]))) throw new AssertionError("Проверка " + i + " из " + total + ": с другими значениями полей ответ неверный. Проверь, что программа вычисляет ответ из полей и правильно обрабатывает все случаи из условия, включая граничные значения");
    }
    System.out.print("{{PASS_MARKER}}");
  }
}

