CASES = [[None, 'wheat: 5 trays\nSeeds in the pot: 10\nWater: 3.75 l a day\nGood conditions\nSprouts in 5 days\n'], [{'plant': '"pea"', 'seeds': '"96"', 'temp': '18', 'humidity': '60'}, 'pea: 4 trays\nSeeds in the pot: 0\nWater: 3.0 l a day\nGood conditions\nSprouts in 5 days\n'], [{'plant': '"oat"', 'seeds': '"200"', 'temp': '25', 'humidity': '75'}, 'oat: 8 trays\nSeeds in the pot: 8\nWater: 6.0 l a day\nGood conditions\nSprouts in 5 days\n'], [{'plant': '"rye"', 'seeds': '"50"', 'temp': '26', 'humidity': '80'}, 'rye: 2 trays\nSeeds in the pot: 2\nWater: 1.5 l a day\nBad conditions\nSprouts in 8 days\n'], [{'plant': '"bean"', 'seeds': '"23"', 'temp': '17', 'humidity': '65'}, 'bean: 0 trays\nSeeds in the pot: 23\nWater: 0.0 l a day\nBad conditions\nSprouts in 8 days\n'], [{'plant': '"corn"', 'seeds': '"144"', 'temp': '21', 'humidity': '59'}, 'corn: 6 trays\nSeeds in the pot: 0\nWater: 4.5 l a day\nBad conditions\nSprouts in 8 days\n']]


